beforeExample:
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IAdaptable;

public class MyClass {
    public void myMethod(Object lastSegmentObj) {
        // This is the target pattern
        IResource selectedResource = ((IAdaptable) lastSegmentObj).getAdapter(IResource.class);
        System.out.println("Resource: " + selectedResource);
    }

    public void anotherMethod(Object obj) throws CoreException {
        // Another instance for completeness
        Object result = ((IAdaptable) obj).getAdapter(String.class); 
        System.out.println("Result: " + result);
    }
}

afterExample:
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.Adapters; // Added import
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IAdaptable;

public class MyClass {
    public void myMethod(Object lastSegmentObj) {
        // Transformed pattern
        IResource selectedResource = Adapters.adapt(lastSegmentObj, IResource.class);
        System.out.println("Resource: " + selectedResource);
    }

    public void anotherMethod(Object obj) throws CoreException {
        // Transformed pattern
        Object result = Adapters.adapt(obj, String.class); 
        System.out.println("Result: " + result);
    }
}

negativeExample:
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.IAdaptable;
import org.eclipse.core.runtime.CoreException;

public class NegativeMyClass {
    public void noMatchMethod(IAdaptable adaptableObj) {
        // Should not match: not a cast expression
        IResource resource = adaptableObj.getAdapter(IResource.class);
        System.out.println("Directly adaptable: " + resource);
    }

    public void noMatchOtherCast(Object obj) {
        // Should not match: different method call (substring vs getAdapter)
        String s = ((String) obj).substring(0);
        System.out.println("Substring: " + s);
    }

    public void noMatchDifferentAdapter(Object obj) {
        // Should not match: different adapter interface cast, no getAdapter() call
        java.io.Serializable ser = ((java.io.Serializable) obj);
        System.out.println("Serializable: " + ser);
    }
}
